import{_ as a,c as i,o as t,ae as r}from"./chunks/framework.CXzlQjHd.js";const u=JSON.parse('{"title":"Architecture Decision Record 1: Tailwind CSS for Styling Library","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr-choose-styling-library/adr1.md","filePath":"architecture/adr-choose-styling-library/adr1.md"}'),o={name:"architecture/adr-choose-styling-library/adr1.md"};function n(s,e,l,c,d,p){return t(),i("div",null,e[0]||(e[0]=[r('<h1 id="architecture-decision-record-1-tailwind-css-for-styling-library" tabindex="-1">Architecture Decision Record 1: Tailwind CSS for Styling Library <a class="header-anchor" href="#architecture-decision-record-1-tailwind-css-for-styling-library" aria-label="Permalink to &quot;Architecture Decision Record 1: Tailwind CSS for Styling Library&quot;">​</a></h1><p>Date: 01/09/2024</p><h1 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h1><p>We are building the fAIr website that requires a responsive and customizable user interface. The stying must be consistent and modern, ensuring a great user experience. The development team has experience using custom CSS but wants to explore CSS frameworks that can save time and effort. We are looking for a framework that is easy to use, customizable, has a large community for support and has a compatible license with HOT.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><p>Easy to use: We want a framework that is simple to learn and can be integrated into our development workflow.</p></li><li><p>Customizable: We want a framework that can be customized to match the HOT brand guidelines and theme.</p></li><li><p>Large community support: We want a framework that has an active community of developers, libraries, and designers that can provide help and resources when needed.</p></li><li><p>Time-saving: We want a framework that can save time and effort in styling the UI.</p></li><li><p>License: We want a framework that is open source and compatible with HOT licensing requirement.</p></li><li><p>Size &amp; Performance: We want a framework that ships small CSS to the client, and would not bloat the website.</p></li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><p><a href="https://getbootstrap.com/" target="_blank" rel="noreferrer">Bootstrap</a>: A popular CSS framework with a lot of pre-built components and a large community of developers.</p></li><li><p><a href="https://mui.com/material-ui/" target="_blank" rel="noreferrer">Material UI</a>: A CSS framework based on Google&#39;s Material Design language with pre-built components for UI development.</p></li><li><p><a href="https://v2.chakra-ui.com/" target="_blank" rel="noreferrer">Chakra UI</a>: Create accessible React apps with speed.</p></li><li><p>SCSS: CSS with superpowers.</p></li><li><p><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a>: A utility-first CSS framework with a focus on customization and efficiency.</p></li></ul><h1 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h1><p>After considering the options, we will use Tailwind CSS for the following reasons:</p><ul><li><p>Easy to use: Tailwind&#39;s approach is simple and easy to understand. Its utility classes make building a UI faster.</p></li><li><p>Customizable: Tailwind allows for customization by providing a set of configuration files that allow developers to modify the framework&#39;s default styles with ease.</p></li><li><p>Large community support: Tailwind has a very active community of developers, open source libraries, and designers that are consistently creating new resources, plugins, and tools.</p></li><li><p>Time-saving: Tailwind can save time, enabling the team to focus on other areas of the project.</p></li><li><p>License: Tailwing&#39;s license is MIT, which complies with HOT licensing requirement.</p></li><li><p>Size &amp; Performance: Unlike other considered options, Tailwing is smaller and ships less than 10KB to the client.</p></li></ul><p>We will use Tailwind CSS&#39;s utility classes to build the UI for our project. The development team will use its atomic and modular design system to write efficient and scalable CSS code. We will leverage Tailwind&#39;s pre-built templates and visual components to speed up the development process while utilizing custom styles to match the branding and theme of HOT.</p><h1 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h1><p>Proposed.</p><h1 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h1><ul><li>New developers onboarding this project may face a slight learning curve.</li><li>Since most UI elements will be built from scratch, there could be minor development slowdown compared to using component-based frameworks like Material UI or Chakra UI. Although component-based frameworks may also introduce some learning curve and inflexibility.</li></ul>',16)]))}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
